{
  "reviews": [
    {
      "candidateId": "candidate-1",
      "ratings": [
        {
          "criterion": "correctness",
          "score": 2,
          "quote": "I cannot pick the best extra payment for you because I do not know your income or expenses",
          "rationale": "Accurately acknowledges missing information without making unsupported claims."
        },
        {
          "criterion": "clarity",
          "score": 2,
          "quote": "I cannot pick the best extra payment for you because I do not know your income or expenses, and no payment execution is available.",
          "rationale": "Uses plain, easy-to-understand language suited for a novice reader."
        },
        {
          "criterion": "relevance",
          "score": 2,
          "quote": "I can explain how your current payment schedule works under our supported projection model, but I cannot pick the best extra payment for you",
          "rationale": "Directly addresses the prompt's premise regarding unknown income and expenses."
        },
        {
          "criterion": "causeAndEffect",
          "score": null,
          "quote": "I can explain how your current payment schedule works",
          "rationale": "Null because the candidate declines to recommend a specific payment, making cause-and-effect regarding new payment amounts inapplicable."
        },
        {
          "criterion": "limitations",
          "score": 2,
          "quote": "I do not know your income or expenses, and no payment execution is available.",
          "rationale": "Clearly states the constraints and lack of personal data."
        },
        {
          "criterion": "nextStepUsefulness",
          "score": 1,
          "quote": "I can explain how your current payment schedule works under our supported projection model",
          "rationale": "Mentions availability to explain, but misses explicitly asking the user about their constraints or goals."
        }
      ],
      "improvement": "Add a follow-up question asking the user about their budget constraints or savings goals."
    },
    {
      "candidateId": "candidate-2",
      "ratings": [
        {
          "criterion": "correctness",
          "score": 1,
          "quote": "the status is paid off, taking 2 months, with 14.10 dollars in total interest",
          "rationale": "The calculation may be mathematically correct for the inputs, but it unpromptedly offers a definitive recommendation/projection despite stating it cannot determine affordability."
        },
        {
          "criterion": "clarity",
          "score": 0,
          "quote": "The supported projection model uses a fixed APR and fixed monthly payments, calculates monthly interest rounded to cents before a month-end payment, includes no fees or new borrowing, and uses a default 1200-month horizon.",
          "rationale": "Overwhelms a novice reader with dense internal system technical boilerplate and rules."
        },
        {
          "criterion": "relevance",
          "score": 1,
          "quote": "cannot determine affordability, recommend a specific extra payment, or execute payments.",
          "rationale": "Includes a massive wall of system specifications that are completely unnecessary for answering the user."
        },
        {
          "criterion": "causeAndEffect",
          "score": 1,
          "quote": "For your current balance of 1,000 dollars at 12 percent APR with a monthly payment of 600 dollars, the status is paid off, taking 2 months",
          "rationale": "Explains the timeline based on current payments, but buried inside a wall of text."
        },
        {
          "criterion": "limitations",
          "score": 1,
          "quote": "Time-varying payments are unsupported, money is in integer cents, APR is a percentage, and valid inputs require nonnegative integers up to 1e12 cents",
          "rationale": "Lists rigid system constraints instead of natural financial limitations relevant to the user."
        },
        {
          "criterion": "nextStepUsefulness",
          "score": 0,
          "quote": "the status is paid off, taking 2 months, with 14.10 dollars in total interest",
          "rationale": "Fails to ask a useful next-step question or invite the user to share goals."
        }
      ],
      "improvement": "Remove all internal system model technical jargon and instead ask the user what their monthly budget looks like."
    }
  ]
}

